/// Returns the element at `i` without checking bounds.
///
/// # Safety
///
/// `i` must be less than `v.len()`.
unsafe fn get_unchecked(v: &[i32], i: usize) -> i32 {
    // SAFETY: the caller promises i < v.len().
    unsafe { *v.as_ptr().add(i) }
}

fn main() {
    let v = [10, 20, 30];
    // SAFETY: 2 < 3.
    let x = unsafe { get_unchecked(&v, 2) };
    println!("{x}");
}

use std::slice;

fn split_at_mut(values: &mut [i32], mid: usize) -> (&mut [i32], &mut [i32]) {
    let len = values.len();
    let ptr = values.as_mut_ptr();
    assert!(mid <= len, "mid out of range");
    // SAFETY: mid <= len, so the two halves are inside the slice and don't overlap.
    unsafe {
        (
            slice::from_raw_parts_mut(ptr, mid),
            slice::from_raw_parts_mut(ptr.add(mid), len - mid),
        )
    }
}

fn main() {
    let mut v = [1, 2, 3, 4, 5, 6];
    let (a, b) = split_at_mut(&mut v, 3);
    a[0] = 10;
    b[0] = 40;
    println!("{v:?}");
}

