fn split(values: &mut [i32]) -> (&mut [i32], &mut [i32]) {
    let len = values.len();
    let mid = len / 2;
    let p = values.as_mut_ptr();
    // SAFETY: mid <= len, so the halves are in bounds and disjoint.
    unsafe {
        (
            std::slice::from_raw_parts_mut(p, mid),
            std::slice::from_raw_parts_mut(p.add(mid), len - mid),
        )
    }
}

fn main() {
