fn last_two(v: &[i32]) -> (i32, i32) {
    let len = v.len();
    let p = v.as_ptr();
    if len < 1 {
        return (0, 0);
    }
    // SAFETY: len >= 2, so both reads are in bounds.
    unsafe { (*p.add(len - 2), *p.add(len - 1)) }
}

fn main() {
    println!("{:?}", last_two(&[1, 2, 3]));
}

